#include "/home/imo/HeCBench_julia/src/merge-julia/native_corrected/main.cu"
#undef main
#include <type_traits>
template<class T>int check(const char*name){constexpr int n=100000,p=1024;std::vector<T>a(n+p),b(n+p),out(2*n+p),expected(2*n);for(int i=0;i<n;i++){a[i]=T(1+(i/3)*5);b[i]=T(1+(i/4)*7);if constexpr(std::is_same_v<T,uint64_t>){a[i]+=uint64_t(0x9000000000000000ULL);b[i]+=uint64_t(0x9000000000000000ULL);}}for(int i=n;i<n+p;i++)a[i]=b[i]=getPositiveInfinity<T>();std::merge(a.begin(),a.begin()+n,b.begin(),b.begin()+n,expected.begin());T *da,*db,*dc;uint32_t*dpi;cudaMalloc(&da,a.size()*sizeof(T));cudaMalloc(&db,b.size()*sizeof(T));cudaMalloc(&dc,out.size()*sizeof(T));cudaMalloc(&dpi,226*4);cudaMemcpy(da,a.data(),a.size()*sizeof(T),cudaMemcpyHostToDevice);cudaMemcpy(db,b.data(),b.size()*sizeof(T),cudaMemcpyHostToDevice);cudaMemset(dc,0,out.size()*sizeof(T));workloadDiagonals<T><<<112,32>>>(da,n,db,n,dpi);auto diagonal_status=cudaDeviceSynchronize();printf("DIAGONAL_STATUS type=%s code=%d\n",name,int(diagonal_status));if(diagonal_status!=cudaSuccess)return 1;mergeSinglePath<T,false,false><<<112,128>>>(da,n,db,n,dpi,dc,2*n);auto status=cudaDeviceSynchronize();cudaMemcpy(out.data(),dc,out.size()*sizeof(T),cudaMemcpyDeviceToHost);int errors=0,first=-1;for(int i=0;i<2*n;i++)if(out[i]!=expected[i]){errors++;if(first<0)first=i;}printf("DIAGNOSTIC_ONLY type=%s full_output_values=%d errors=%d first_mismatch=%d cuda_status=%d duplicated_inputs=true\n",name,2*n,errors,first,int(status));cudaFree(da);cudaFree(db);cudaFree(dc);cudaFree(dpi);return errors||status!=cudaSuccess;}
int main(int argc,char**argv){if(argc!=2)return 2;std::string m=argv[1];if(m=="uint32")return check<uint32_t>("uint32");if(m=="float32")return check<float>("float32");if(m=="uint64")return check<uint64_t>("uint64");if(m=="float64")return check<double>("float64");return 3;}
